home.js:
// Use textContent for CMS data. Do not interpolate visitor content as HTML.
function render(){
 const settings=NOVA.theme.settings;
 document.getElementById('eyebrow').textContent=settings.eyebrow;
 document.getElementById('headline').textContent=settings.headline;
 document.getElementById('intro').textContent=NOVA.context.page?.content||NOVA.design.texts.hero_description;
 document.getElementById('catalog-link').hidden=!NOVA.settings.shop_enabled;
 document.getElementById('selection').hidden=!NOVA.settings.shop_enabled;
 document.getElementById('contact').hidden=!settings['contact-form'];
 const root=document.getElementById('products');root.replaceChildren();
 for(const p of NOVA.products.slice(0,3)){
  const card=document.createElement('article');card.className='card';
  const a=document.createElement('a');a.href='/product/'+p.id;
  const title=document.createElement('h3');title.textContent=p.name;
  if(p.image_url){const img=document.createElement('img');img.className='photo';img.src=p.image_url;img.alt=p.name;img.loading='lazy';a.append(img)}
  a.append(title);card.append(a);
  if(settings['show-prices']){const price=document.createElement('strong');price.textContent=NOVA.money(Math.round(p.price*100));card.append(price)}
  root.append(card);
 }
}
document.getElementById('contact').addEventListener('click',()=>NOVA.forms.open(NOVA.theme.settings['contact-form']).catch(e=>document.getElementById('status').textContent=e.message));
render();addEventListener('nova:context',render);

catalog.js:
function render(){
 const query=document.getElementById('search').value.trim().toLowerCase(),root=document.getElementById('products');root.replaceChildren();
 for(const p of NOVA.products.filter(p=>p.name.toLowerCase().includes(query))){
  const card=document.createElement('article');card.className='card';
  const a=document.createElement('a');a.href='/product/'+p.id;
  if(p.image_url){const img=document.createElement('img');img.className='photo';img.src=p.image_url;img.alt=p.name;img.loading='lazy';a.append(img)}
  const h=document.createElement('h3');h.textContent=p.name;a.append(h);card.append(a);
  const price=document.createElement('strong');price.textContent=NOVA.money(Math.round(p.price*100));card.append(price);
  const actions=document.createElement('div');actions.className='actions';
  const button=document.createElement('button');button.textContent=p.variants.length?'Выбрать вариант':'В корзину';button.disabled=!p.variants.length&&p.stock===0;
  if(p.variants.length){const link=document.createElement('a');link.href='/product/'+p.id;link.className='button';link.textContent='Выбрать вариант';actions.append(link)}
  else{button.addEventListener('click',async()=>{try{await NOVA.cart.add(p.id);document.getElementById('status').textContent='Товар добавлен'}catch(e){document.getElementById('status').textContent=e.message}});actions.append(button)}
  card.append(actions);root.append(card);
 }
 if(!root.children.length)root.textContent=NOVA.design.texts.no_products;
}
document.getElementById('search').addEventListener('input',render);
document.getElementById('cart').addEventListener('click',()=>NOVA.cart.open().catch(e=>document.getElementById('status').textContent=e.message));
render();addEventListener('nova:context',render);

product.js:
let productId;
function render(){
 const p=NOVA.context.product;if(!p)return;
 if(productId!==p.id){productId=p.id;
  for(const [id,value]of Object.entries({name:p.name,description:p.description,category:p.category}))document.getElementById(id).textContent=value;
  const photo=document.getElementById('photo');photo.replaceChildren();if(p.image_url){const img=document.createElement('img');img.src=p.image_url;img.alt=p.name;img.className='photo';photo.append(img)}
  const picker=document.getElementById('variant');picker.replaceChildren();for(const v of p.variants){const option=document.createElement('option');option.value=v.name;option.textContent=v.name;option.disabled=v.stock<=0;picker.append(option)}
  document.getElementById('variant-label').hidden=!p.variants.length;
 }
 const v=p.variants.find(v=>v.name===document.getElementById('variant').value),source=v||p;
 document.getElementById('price').textContent=NOVA.money(Math.round(source.price*100));document.getElementById('stock').textContent='В наличии: '+source.stock;document.getElementById('add').disabled=source.stock<=0;
}
document.getElementById('variant').addEventListener('change',render);
document.getElementById('add').addEventListener('click',async()=>{try{const p=NOVA.context.product;await NOVA.cart.add(p.id,p.variants.length?document.getElementById('variant').value:'');document.getElementById('status').textContent='Товар добавлен'}catch(e){document.getElementById('status').textContent=e.message}});
document.getElementById('cart').addEventListener('click',()=>NOVA.cart.open().catch(e=>document.getElementById('status').textContent=e.message));
render();addEventListener('nova:context',render);
